#!/usr/bin/env python3
from pwn import *
context.log_level = 'error'

def try_password(password):
    try:
        conn = remote('rev.chal.csaw.io', 5000)

        # Try a few predefined paths to reach Easter egg room
        paths = [[1,2], [2,1], [3,2], [1,1,2], [2,2,1]]

        for path in paths:
            try:
                # Navigate the path
                for direction in path:
                    conn.recvuntil(b"Choice: ")
                    conn.sendline(str(direction).encode())

                # Try the password
                conn.recvuntil(b"decimal form?: ", timeout=1)
                conn.sendline(str(password).encode())

                # Get response
                result = conn.recvline(timeout=1).decode().strip()
                if 'flag{' in result.lower() or 'incorrect' in result.lower():
                    return f"Path {'->'.join(map(str,path))}: {result}"
            except:
                continue

        return "No valid response"
    except Exception as e:
        return f"Error: {str(e)}"
    finally:
        conn.close()

# Test all passwords
passwords = [2064320989, 2641499740, 3542801286, 1298664772, 127040641]
results = []

for password in passwords:
    print(f"\nTrying password: {password}")
    result = try_password(password)
    print(result)
    if 'flag{' in result.lower():
        results.append(result)

print("\nFound flag pieces:")
for r in results:
    print(r)

