#!/usr/bin/env python3
from pwn import *

def test_password(path, password):
    try:
        conn = remote('rev.chal.csaw.io', 5000)
        print(f"\nTrying path {path} with password {password}")

        # Read initial prompt
        conn.recvuntil(b"Choice: ")

        # Follow the path
        for choice in path:
            conn.sendline(str(choice).encode())
            response = conn.recvuntil(b"Choice: ", timeout=1)
            print(response.decode())

            if b"password" in response:
                conn.sendline(str(password).encode())
                flag_resp = conn.recvuntil(b"Choice: ", timeout=1)
                print(flag_resp.decode())
                if b"flag" in flag_resp:
                    print(f"Found a flag piece with password {password} on path {path}!")
                    return True
                return False

            if b"dead end" in response or b"exit" in response:
                return False

    except EOFError:
        return False
    finally:
        if conn:
            conn.close()
    return False

# List of passwords to try
passwords = [2064320989, 2641499740, 3542801286, 1298664772, 127040641]

# Define some basic paths to try first
basic_paths = [[1], [2], [3]]

# Try each password with each basic path
for password in passwords:
    for path in basic_paths:
        if test_password(path, password):
            print(f"Success with password {password} on path {path}")

